using System;\nusing System.Data;\nusing System.Data.SqlClient;\nusing System.IO;\nusing System.Web.UI;\nusing System.Web.UI.WebControls;\n\nnamespace Training.Admin\n{\n    public partial class SessionAttendanceReport : Page\n    {\n        private readonly clsDataAccess obj = new clsDataAccess();\n        protected void Page_Load(object sender, EventArgs e) { if (!IsPostBack) BindReport(); }\n        protected void btnSearch_Click(object sender, EventArgs e) { BindReport(); }\n        protected void btnReset_Click(object sender, EventArgs e) { txtTrainingID.Text = \"\"; txtFromDate.Text = \"\"; txtToDate.Text = \"\"; BindReport(); }\n        private void BindReport() { try { string query = @\"SELECT SM.TrainingID,TD.Batch,SM.SessionID,SM.SessionNo,SM.SessionName,TP.TopicName,SM.SessionDate,SM.StartTime,SM.EndTime,SM.TrainerID,COUNT(SA.EmpID) TotalMarked,SUM(CASE WHEN ISNULL(SA.AttendanceStatus,'')='Present' THEN 1 ELSE 0 END) Present,SUM(CASE WHEN ISNULL(SA.AttendanceStatus,'')='Absent' THEN 1 ELSE 0 END) Absent,SUM(CASE WHEN ISNULL(SA.AttendanceStatus,'') NOT IN ('Present','Absent') THEN 1 ELSE 0 END) Pending,ISNULL(SM.AttendanceStatus,'Pending') AttendanceStatus,SM.SessionStatus FROM SessionMaster SM INNER JOIN TrainingDetails TD ON SM.TrainingID=TD.TrainingID LEFT JOIN TopicMaster TP ON SM.TopicID=TP.TopicID LEFT JOIN SessionAttendance SA ON SM.SessionID=SA.SessionID AND SM.TrainingID=SA.TrainingID WHERE (@TrainingID='' OR SM.TrainingID LIKE '%' + @TrainingID + '%') AND (@FromDate='' OR TRY_CONVERT(date,SM.SessionDate,105)>=TRY_CONVERT(date,@FromDate,23)) AND (@ToDate='' OR TRY_CONVERT(date,SM.SessionDate,105)<=TRY_CONVERT(date,@ToDate,23)) GROUP BY SM.TrainingID,TD.Batch,SM.SessionID,SM.SessionNo,SM.SessionName,TP.TopicName,SM.SessionDate,SM.StartTime,SM.EndTime,SM.TrainerID,SM.AttendanceStatus,SM.SessionStatus ORDER BY TRY_CONVERT(date,SM.SessionDate,105),SM.TrainingID,SM.SessionNo\"; SqlParameter[] p = { new SqlParameter(\"@TrainingID\", txtTrainingID.Text.Trim()), new SqlParameter(\"@FromDate\", txtFromDate.Text.Trim()), new SqlParameter(\"@ToDate\", txtToDate.Text.Trim()) }; DataTable dt = obj.GetDataTable(query, p); gvReport.DataSource = dt; gvReport.DataBind(); Session[\"SessionAttendanceReportData\"] = dt; lblMsg.Text = dt.Rows.Count + \" record(s) found.\"; } catch (Exception ex) { lblMsg.Text = ex.Message; } }\n        protected void btnExcel_Click(object sender, EventArgs e) { DataTable dt = Session[\"SessionAttendanceReportData\"] as DataTable; if (dt == null) { BindReport(); dt = Session[\"SessionAttendanceReportData\"] as DataTable; } gvReport.DataSource = dt; gvReport.DataBind(); Response.Clear(); Response.Buffer = true; Response.AddHeader(\"content-disposition\", \"attachment;filename=SessionAttendanceReport.xls\"); Response.ContentType = \"application/ms-excel\"; StringWriter sw = new StringWriter(); HtmlTextWriter hw = new HtmlTextWriter(sw); gvReport.RenderControl(hw); Response.Write(sw.ToString()); Response.End(); }\n        public override void VerifyRenderingInServerForm(Control control) { }\n    }\n}